def generate_safe_fn(f, df, bounds):
    def safe_f(x):
        if bounds[0] <= x <= bounds[1]:
            return f(x)
        else:
            return bounds[1] if x < bounds[0] else bounds[0]

    def safe_grad(x):
        return df(x, safe_f(x), 1.0)

