import os
import shutil
from queue import Queue
from urllib.parse import urlparse
from litdata.streaming.client import S3Client

def _upload_fn(upload_queue: Queue, remove_queue: Queue, cache_dir: str, output_dir: str) -> None:
    s3 = S3Client()
    output_url = urlparse(output_dir)
    scheme = output_url.scheme

    while True:
        item = upload_queue.get()

        if item is None:
            break  # Termination signal

        if isinstance(item, str):
            temp_dir = None
            file_path = item
        elif isinstance(item, tuple):
            temp_dir, file_path = item
        else:
            raise ValueError("Invalid item in upload_queue")

        # Adjust the local file path relative to cache_dir if needed
        if not file_path.startswith(cache_dir):
            file_path = os.path.join(cache_dir, file_path)

        try:
            # Handle the upload based on the scheme
            if scheme == "s3":
                remote_path = output_url.path.lstrip("/")
                s3.client.upload_file(file_path, output_url.netloc, remote_path)
